pub(crate) fn is_unsigned_opcode(op: Op) -> bool {
    // Don't have to be exhaustive, only relevant for legacy target checking ...
    matches!(
        op,
        OpShiftRightLogical
            | OpUGreaterThan
            | OpUGreaterThanEqual
            | OpULessThan
            | OpULessThanEqual
            | OpUConvert
            | OpUDiv
            | OpUMod
            | OpUMulExtended
            | OpConvertUToF
            | OpConvertFToU
    )
}

pub(crate) fn is_unsigned_glsl_opcode(op: GLSLstd450) -> bool {
    // Don't have to be exhaustive, only relevant for legacy target checking ...
    matches!(
        op,
        GLSLstd450UClamp | GLSLstd450UMin | GLSLstd450UMax | GLSLstd450FindUMsb
    )
}

use BufferPackingStandard::*;

pub(crate) fn packing_is_vec4_padded(packing: BufferPackingStandard) -> bool {
    matches!(
        packing,
        BufferPackingHLSLCbuffer
            | BufferPackingHLSLCbufferPackOffset
            | BufferPackingStd140
            | BufferPackingStd140EnhancedLayout
    )
}

pub(crate) fn packing_is_hlsl(packing: BufferPackingStandard) -> bool {
    matches!(
        packing,
        BufferPackingHLSLCbuffer | BufferPackingHLSLCbufferPackOffset
    )
}

pub(crate) fn packing_has_flexible_offset(packing: BufferPackingStandard) -> bool {
    !matches!(
        packing,
        BufferPackingStd140 | BufferPackingStd430 | BufferPackingScalar | BufferPackingHLSLCbuffer
    )
}

pub(crate) fn packing_is_scalar(packing: BufferPackingStandard) -> bool {
    matches!(
        packing,
        BufferPackingScalar | BufferPackingScalarEnhancedLayout
    )
}

pub(crate) fn packing_to_substruct_packing(
    packing: BufferPackingStandard,
) -> BufferPackingStandard {
    match packing {
        BufferPackingStd140EnhancedLayout => BufferPackingStd140,
        BufferPackingStd430EnhancedLayout => BufferPackingStd430,
        BufferPackingHLSLCbufferPackOffset => BufferPackingHLSLCbuffer,
        BufferPackingScalarEnhancedLayout => BufferPackingScalar,
        _ => packing,
    }
}

